function clampNum(v, lo, hi) { return v < lo ? lo : (v > hi ? hi : v); }

function estimateWidth(text, fontSize) {
  var w = 0;
  for (var i = 0; i < text.length; i++) {
    var code = text.charCodeAt(i);
    if (code > 127) { w += fontSize; }
    else if (code === 32) { w += fontSize * 0.28; }
    else { w += fontSize * 0.58; }
  }
  return w;
}

function metricWidthOf(metrics, index) {
  if (!metrics || !metrics[index]) { return 0; }
  var m = metrics[index];
  var w = m.width;
  if (typeof w !== 'number') { w = m.w; }
  if (typeof w !== 'number' && m.size) { w = m.size.width; }
  if (typeof w !== 'number' && m.bounds) { w = m.bounds.width; }
  if (typeof w !== 'number' || !isFinite(w) || w <= 0) { return 0; }
  return w;
}

function pickFontSize(text, index, metrics, maxWidth, wanted, minSize) {
  var mw = metricWidthOf(metrics, index);
  var w = mw > 0 ? mw : estimateWidth(text, wanted);
  if (w > maxWidth && w > 0) {
    return Math.max(minSize, wanted * (maxWidth / w));
  }
  return wanted;
}

function roundRectCommands(x, y, w, h, r) {
  var k = 0.5522847498 * r;
  return [
    { type: 'M', x: x + r, y: y },
    { type: 'L', x: x + w - r, y: y },
    { type: 'C', x1: x + w - r + k, y1: y, x2: x + w, y2: y + r - k, x: x + w, y: y + r },
    { type: 'L', x: x + w, y: y + h - r },
    { type: 'C', x1: x + w, y1: y + h - r + k, x2: x + w - r + k, y2: y + h, x: x + w - r, y: y + h },
    { type: 'L', x: x + r, y: y + h },
    { type: 'C', x1: x + r - k, y1: y + h, x2: x, y2: y + h - r + k, x: x, y: y + h - r },
    { type: 'L', x: x, y: y + r },
    { type: 'C', x1: x, y1: y + r - k, x2: x + r - k, y2: y, x: x + r, y: y },
    { type: 'Z' }
  ];
}

var TITLE_TEXT = '解一元一次方程 6x + 5 = 2x + 11';
var STEP_TEXT = [
  '① 移项',
  '② 合并同类项',
  '③ 系数化为 1'
];
var EXPR_TEXT = [
  '6x − 2x = 11 − 5',
  '4x = 6',
  'x = 6 ÷ 4 = 3/2'
];

const visual = {
  prepare: function (input) {
    var items = [{ kind: 'text', payload: TITLE_TEXT }];
    for (var i = 0; i < STEP_TEXT.length; i++) {
      items.push({ kind: 'text', payload: STEP_TEXT[i] });
    }
    for (var j = 0; j < EXPR_TEXT.length; j++) {
      items.push({ kind: 'text', payload: EXPR_TEXT[j] });
    }
    return items;
  },
  render: function (input, metrics) {
    var W = (input.viewport && input.viewport.widthDu) || 360;
    var H = (input.viewport && input.viewport.heightDu) || 560;
    var margin = W * 0.06;
    var cardX = margin;
    var cardW = W - margin * 2;
    var top = H * 0.155;
    var bottom = H * 0.97;
    var gap = H * 0.045;
    var cardH = (bottom - top - gap * 2) / 3;
    var pad = Math.max(10, cardW * 0.05);

    var paths = [];
    var children = [];

    var fsTitleWanted = clampNum(W * 0.052, 13, 23);
    var fsTitle = pickFontSize(TITLE_TEXT, 0, metrics, cardW, fsTitleWanted, 10);
    children.push({
      type: 'label',
      text: TITLE_TEXT,
      x: W / 2,
      y: H * 0.09,
      fontSize: fsTitle,
      fill: '#1f3350',
      textAnchor: 'middle',
      fontWeight: 'bold'
    });

    var fsStepWanted = clampNum(Math.min(cardW * 0.055, cardH * 0.13), 11, 18);
    var fsExprWanted = clampNum(Math.min(cardW * 0.075, cardH * 0.19), 12, 22);
    var badgeR = clampNum(cardH * 0.14, 9, 15);

    for (var i = 0; i < STEP_TEXT.length; i++) {
      var cardY = top + i * (cardH + gap);
      paths.push({
        id: 'card' + i,
        commands: roundRectCommands(cardX, cardY, cardW, cardH, Math.min(14, cardH * 0.12))
      });
      children.push({
        type: 'path',
        pathId: 'card' + i,
        fill: '#eef4ff',
        stroke: '#7ea0d2',
        strokeWidth: 1.4
      });

      if (i < STEP_TEXT.length - 1) {
        var ay0 = cardY + cardH + gap * 0.18;
        var ay1 = cardY + cardH + gap * 0.82;
        paths.push({ id: 'arrow' + i, commands: visualSdk.arrow(W / 2, ay0, W / 2, ay1, {}) });
        children.push({
          type: 'path',
          pathId: 'arrow' + i,
          fill: 'none',
          stroke: '#4a6fa5',
          strokeWidth: 1.6
        });
      }

      var bcx = cardX + pad + badgeR;
      var bcy = cardY + cardH * 0.30;
      paths.push({ id: 'badge' + i, commands: visualSdk.circle(bcx, bcy, badgeR) });
      children.push({ type: 'path', pathId: 'badge' + i, fill: '#3f6fbf', stroke: 'none' });
      children.push({
        type: 'label',
        text: String(i + 1),
        x: bcx,
        y: bcy + badgeR * 0.36,
        fontSize: badgeR * 1.1,
        fill: '#ffffff',
        textAnchor: 'middle',
        fontWeight: 'bold'
      });

      var stepTitle = STEP_TEXT[i];
      var stepX = bcx + badgeR + pad * 0.5;
      var stepMaxW = cardX + cardW - pad - stepX;
      var fsStep = pickFontSize(stepTitle, i + 1, metrics, stepMaxW, fsStepWanted, 9);
      children.push({
        type: 'label',
        text: stepTitle,
        x: stepX,
        y: bcy + fsStep * 0.35,
        fontSize: fsStep,
        fill: '#2b4f86',
        textAnchor: 'start',
        fontWeight: 'bold'
      });

      var expr = EXPR_TEXT[i];
      var fsExpr = pickFontSize(expr, i + 4, metrics, cardW - pad * 2, fsExprWanted, 11);
      children.push({
        type: 'label',
        text: expr,
        x: cardX + pad,
        y: cardY + cardH * 0.80,
        fontSize: fsExpr,
        fill: '#12233d',
        textAnchor: 'start'
      });
    }

    return {
      schemaVersion: 1,
      sceneId: 'linear-eq-flow',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
